%[text] # Es 1
f1 = @(x) (2.*log(x+2))./(sqrt(x+1));
f2 = @(x) (x.^2 + 2.*x + 1)./(x.^2 + 1);

x1 = linspace(1, 2, 100);
x2 = linspace(0, 5, 100);

y1 = f1(x1);
y2 = f2(x2);

disp("Plot 1"); %[output:336661c6]
plot(x1, y1, x2, y2); %[output:9a05ce92]

disp("Plot 2"); %[output:03f566d0]
plot(x1, y1); %[output:901d7e9f]

disp("Plot 3"); %[output:53ed0aa7]
plot(x2, y2, "r--"); %[output:8114c38e]

%%
%[text] ## Polysum
function z = polysum(p, q)
    lp = length(p);
    lq = length(q);
    if lp ~= lq
        if lq < lp
            temp = p;
            p = q;
            q = temp;
        end
        p = [zeros(abs(lq-lp), 1) p];
    end
    z = p + q;
end

a = [1 2 3] %[output:698d1d0f]
b = [1 2] %[output:9bfb4954]
z = polysum(b, a) %[output:30a3590c]
roots(z) %[output:99dd51ce]

