%[text] ## Es finali
disp("Es finali") %[output:8d1bd2b7]

% 1
disp("Es 1") %[output:1ac52e97]

p = [1 -1 4 -1] %[output:91762eea]
polyder(p) %[output:4308567f]

% 2
disp("Es 2") %[output:5de4f54c]
p = [1 0 -1 4];
q = [1 6 0 -24 -1 -30];

x = linspace(-2, 1, 100);
r_p = roots(p) %[output:3b6d278a]
r_p = r_p(r_p==real(r_p)) %[output:4aa46ed2]

plot(x, polyval(p, x), r_p, r_p * 0, "r*") %[output:218f5b8f]

x = linspace(-6, 3, 100);
r_q = roots(q) %[output:5c02620f]
r_q = r_q(r_q==real(r_q)) %[output:1a61f7b4]

plot(x, polyval(q, x), r_q, r_q * 0, "r*") %[output:05765244]

% test polyint
disp("Test polyint") %[output:9e40dd0e]
F = polyint(q) %[output:8a32f35c]
polyval(p, 3) %[output:679f9d9d]

% 4
disp("Es 4") %[output:013d694b]
p = [3 -1 -15 5];
x = linspace(-2, 2, 100);
p_r = roots(polyder(p)) %[output:10c994b3]

plot(x, polyval(p, x), p_r, polyval(p, p_r), "r*") %[output:6ee6fec2]


